    uk: Object.freeze(['Авторизація пов’язує активну сесію з перевіреним акаунтом через підтримуваний гаманець, Google, Apple або Telegram; клієнтський заголовок і відображуване ім’я не доводять особу.', 'Увійдіть через офіційний елемент і завершіть перевірку, після чого нова дійсна серверна сесія замінить застарілу; підтримка ніколи не просить seed-фразу чи приватний ключ.']),
    es: Object.freeze(['La autenticación vincula la sesión activa con una cuenta verificada mediante wallet, Google, Apple o Telegram; una cabecera del cliente o un nombre visible no prueban identidad.', 'Inicia sesión desde el control oficial y completa el desafío para que la sesión válida más reciente sustituya el estado obsoleto; soporte nunca pide una frase semilla ni una clave privada.']),
    tr: Object.freeze(['Kimlik doğrulama etkin oturumu desteklenen cüzdan, Google, Apple veya Telegram akışıyla doğrulanmış hesaba bağlar; istemci başlığı ya da görünen ad kimlik kanıtı değildir.', 'Resmî denetimden giriş yapıp doğrulamayı tamamlayın; en yeni geçerli sunucu oturumu eski durumu değiştirsin. Destek seed ifadesi veya özel anahtar istemez.']),
    ar: Object.freeze(['تربط المصادقة الجلسة النشطة بحساب موثّق عبر المحفظة المدعومة أو Google أو Apple أو Telegram؛ ولا يُعد عنوان العميل أو اسم العرض دليلاً للهوية.', 'سجّل الدخول من الأداة الرسمية وأكمل التحقق لتستبدل أحدث جلسة خادم صالحة الحالة القديمة؛ ولا يطلب الدعم أبداً عبارة الاسترداد أو المفتاح الخاص.']),
    zh: Object.freeze(['身份验证会通过受支持的钱包、Google、Apple 或 Telegram 流程，把当前会话绑定到验证账户；客户端请求头或显示名称不能证明身份。', '请从官方入口登录并完成验证，让最新有效服务器会话替换过期状态；支持人员绝不会索要助记词或私钥。']),
    he: Object.freeze(['האימות קושר את ההפעלה הפעילה לחשבון מאומת דרך ארנק נתמך, Google, Apple או Telegram; כותרת לקוח או שם תצוגה אינם הוכחת זהות.', 'היכנסו דרך הבקרה הרשמית והשלימו את האתגר כדי שהפעלת השרת התקפה והחדשה תחליף מצב ישן; התמיכה לעולם אינה מבקשת משפט שחזור או מפתח פרטי.']),
