    ru: Object.freeze(['Вход через Telegram проверяет свежие init data Mini App и сопоставляет стабильный идентификатор с каноническим аккаунтом; имя в Telegram не используется как ключ владения.', 'Запустите официальную Mini App или форму входа и подтвердите её, пока данные актуальны; допустимую связь с существующим wallet-аккаунтом сервер разрешает приватно, не раскрывая её в публичном интерфейсе.']),
    uk: Object.freeze(['Вхід через Telegram перевіряє свіжі init data Mini App і зіставляє стабільний ідентифікатор із канонічним акаунтом; ім’я в Telegram не використовується як ключ володіння.', 'Запустіть офіційну Mini App або форму входу й підтвердьте її, поки дані актуальні; дозволений зв’язок з наявним wallet-акаунтом сервер визначає приватно, не розкриваючи його в публічному інтерфейсі.']),
    es: Object.freeze(['El acceso con Telegram verifica init data recientes de la Mini App y asocia su identificador estable a la cuenta canónica; el nombre visible de Telegram no acredita propiedad.', 'Abre la Mini App oficial o el flujo de acceso y apruébalo mientras los datos sean recientes; el servidor resuelve en privado un vínculo elegible con una cuenta wallet existente.']),
    tr: Object.freeze(['Telegram girişi güncel Mini App init verisini doğrular ve kararlı hesap kimliğini kanonik hesaba eşler; Telegram görünen adı sahiplik anahtarı olarak kullanılmaz.', 'Resmî Mini App veya giriş akışını başlatıp veri güncelken onaylayın; mevcut cüzdan hesabıyla uygun bağlantıyı sunucu özel olarak çözer ve bu ilişkiyi genel yüzeylerde açıklamaz.']),
    ar: Object.freeze(['يتحقق تسجيل Telegram من حداثة init data الخاصة بالتطبيق المصغر ويربط المعرّف الثابت بالحساب المرجعي؛ ولا يُستخدم اسم العرض في Telegram مفتاحاً للملكية.', 'شغّل التطبيق المصغر الرسمي أو مسار الدخول ووافق عليه ما دامت البيانات حديثة؛ يحل الخادم الربط المؤهل بحساب محفظة قائم بشكل خاص دون كشف العلاقة علناً.']),
    zh: Object.freeze(['Telegram 登录会验证 Mini App init data 的时效性，并把稳定账户标识映射到规范账户；Telegram 显示名称不会被当作所有权依据。', '请启动官方 Mini App 或登录流程，并在数据仍有效时确认；若可与现有钱包账户关联，服务器会私下解析别名，不在公开界面暴露该关系。']),
    he: Object.freeze(['כניסה דרך Telegram מאמתת נתוני init עדכניים של ה-Mini App וממפה מזהה חשבון יציב לחשבון הקנוני; שם התצוגה ב-Telegram אינו מפתח בעלות.', 'הפעילו את ה-Mini App הרשמי או את תהליך הכניסה ואשרו כשהנתונים טריים; השרת פותר בפרטיות קישור זכאי לחשבון ארנק קיים בלי לחשוף את היחס בממשק ציבורי.']),
