function terminal(locale = 'en') {
  return locale === 'zh' ? '。' : '.'
}

function sentence(value = '', locale = 'en') {
  const clean = ql7Str(value).replace(/[.!?。！？؟]+$/u, '')
  return clean ? `${clean}${terminal(locale)}` : ''
}

export function realizeQl7SupportProductKnowledge({answer = {}, locale = 'en', intent = '', seed = ''} = {}) {
  const topic = ql7Str(answer.topic)
  const localized = P[topic]?.[locale] || null
  if (!localized) return Object.freeze({ supported: false, text: '', fragments: Object.freeze([]) })
  const sourceReceiptId = ql7Str(ql7Arr(answer.sourceReceipts)[0]?.receiptId || ql7Arr(answer.sourceReceipts)[0]?.evidenceId)
  const howTo = ql7Str(intent) === 'how_to' || ql7Str(intent) === 'how_to_question'
  const reverse = !howTo && Number.parseInt(ql7StableHash(`${seed}:${topic}:${locale}`).slice(0, 8), 16) % 2 === 1
  const ordered = reverse ? [localized[1], localized[0]] : howTo ? [localized[1], localized[0]] : [...localized]
  const fragments = Object.freeze(ordered.map((value, index) => Object.freeze({
    factId: `product:${topic}:${howTo ? 'how-to' : 'overview'}:${reverse ? 1 - index : index}`,
    text: sentence(value, locale),
    sourceReceiptId,
  })))
  return Object.freeze({
    supported: true,
    topic,
    locale,
    intent: howTo ? 'how_to' : 'overview',
    text: fragments.map((row) => row.text).join(' '),
    fragments,
    realizationHash: ql7StableHash(JSON.stringify(fragments)),
  })
}

export function getQl7SupportProductKnowledgeRealizerCoverage() {
  const failures = []
  const locales = ['en','ru','uk','es','tr','ar','zh','he']
  for (const [topic, rows] of Object.entries(P)) {
    for (const locale of locales) {
      const minimum = locale === 'zh' ? 18 : ['ar','he'].includes(locale) ? 28 : 40
      if (ql7Arr(rows[locale]).length !== 2 || rows[locale].some((value) => [...ql7Str(value)].length < minimum)) failures.push(`${topic}:${locale}`)
      const realizedLength = [...ql7Arr(rows[locale]).map((value) => sentence(value, locale)).join(' ')].length
      if (realizedLength > 400) failures.push(`${topic}:${locale}:max-graphemes:${realizedLength}`)
    }
  }
  return Object.freeze({
    version: QL7_SUPPORT_PRODUCT_KNOWLEDGE_REALIZER_VERSION,
    topics: Object.keys(P).length,
    locales: locales.length,
    semanticClauseCount: Object.keys(P).length * locales.length * 2,
    failures: Object.freeze(failures),
    ok: failures.length === 0,
  })
}
